$ cat Hello.java
String s = "안녕 java";
System.out.println("문자 수 = " + s.length());
for (String cs : new String[]{"UTF-8", "MS949", "UTF-16"}) {
    byte[] b = s.getBytes(Charset.forName(cs));
    System.out.printf("%-7s %2d 바이트%n", cs, b.length);
    try (OutputStream out = new FileOutputStream("hello-" + cs + ".txt")) {
        out.write(b);
    }
}

$ java -cp out Hello
문자 수 = 7
UTF-8   11 바이트
MS949    9 바이트
UTF-16  16 바이트
기본 charset = UTF-8

$ od -c hello-UTF-8.txt
0000000   안  **  **  녕  **  **       j   a   v   a
0000013
# od -c 는 여러 바이트짜리 글자를 첫 칸에만 쓰고 나머지를 ** 로 채운다.
# 그래서 '안' 이 세 칸을 차지하는 것이 보인다.

$ od -An -tx1 hello-UTF-8.txt
           ec  95  88  eb  85  95  20  6a  61  76  61

$ od -An -tx1 hello-MS949.txt
           be  c8  b3  e7  20  6a  61  76  61

$ ls -l hello-*.txt
        9 hello-MS949.txt
       16 hello-UTF-16.txt
       11 hello-UTF-8.txt

# 같은 일곱 글자가 9 · 11 · 16 바이트다. 어느 것도 7 이 아니다.
